	protected StringBuilder infoScreenSB = new StringBuilder();

	public Artwork getCurrentArtwork() {
		// Index is not set, use default
		if(artworkIndex == -1) {
			artworkIndex = getDefaultArtworkIndex();
		}

		return getArtworkList().get(artworkIndex);
	}

	protected int getDefaultArtworkIndex() {
		// Determine index by artist, default to 0 (if neither preferred nor custom art exists)
		int rv = 0;
		int i = 0;
		int maxPriority = 0;
		
		for(Artwork art : getArtworkList()) {
			// Always override with custom art
			if(art.getArtist().getName().equals("Custom")) {
				rv = i;
				break;
			}

			// Otherwise, choose the preferred artist
			int artistPriorityValue = Main.getProperties().getArtistPriority(art.getArtist().getFolderName());
			if(artistPriorityValue>maxPriority) {
				rv = i;
				maxPriority = artistPriorityValue;
			}

			i++;
		}

		return rv;
	}

	public boolean isImageRevealed() {
		return isPlayer()
				|| getCurrentArtwork().isCurrentImageClothed()
				|| getTotalTimesHadSex(Main.game.getPlayer()) > 0
				|| Main.game.isConcealedSlotsReveal();
	}
	
	public String getCharacterInformationScreen(boolean includePerkTree) {
		infoScreenSB.setLength(0);

		if(Main.getProperties().hasValue(PropertyValue.artwork)) {
			if (hasArtwork()) {
				Artwork artwork = this.getCurrentArtwork();
				String imageString = "";
				int width = 200;
				int percentageWidth = 33;
				CachedImage image = ImageCache.INSTANCE.getImage(artwork.getCurrentImage());
				if (image != null) {
					imageString = image.getImageString();
					width = image.getWidth();
					percentageWidth = image.getPercentageWidth();
				}

				boolean revealed = isImageRevealed();

				infoScreenSB.append(
						"<div style='position:relative; float:right; width:"+percentageWidth+"%; max-width:"+width+"; object-fit:scale-down;'>"
							+ "<div style='width:100%; margin:0;'>"
								+(imageString.isEmpty()
									?"<div style='width:100%; margin:0; text-align:center;'>没有图像！</div>"
									:"<img id='CHARACTER_IMAGE' style='"+(revealed ? "" : "-webkit-filter: brightness(0%);")+" width:100%;' src='"+imageString+"'/>")
								+ "<div class='overlay no-pointer no-highlight' style='text-align:center;'>" // Add overlay div to stop javaFX's insane image drag+drop
									+ (revealed || imageString.isEmpty()
										? ""
										: "<p style='margin-top:50%; font-weight:bold; color:"+PresetColour.BASE_GREY.toWebHexString()+";'>通过性爱解锁！</p>")
								+ "</div>"
                                + (artwork.getArtist().getName().equals("Custom")?"<div class='title-button' id='ARTWORK_DELETE' style='background:transparent; left:auto; right:52px;'>"+SVGImages.SVG_IMAGE_PROVIDER.getDiskDelete()+"</div>":"")
								+ "<div class='title-button' id='ARTWORK_ADD' style='background:transparent; left:auto; right:28px;'>"+SVGImages.SVG_IMAGE_PROVIDER.getAddIcon()+"</div>"
								+ "<div class='title-button' id='ARTWORK_INFO' style='background:transparent; left:auto; right:4px;'>"+SVGImages.SVG_IMAGE_PROVIDER.getInformationIcon()+"</div>"
							+ "</div>"
							+ "<div class='normal-button"+(artwork.getTotalArtworkCount()==1?" disabled":"")+"' id='ARTWORK_PREVIOUS' style='float:left; width:10%; margin:0; padding:0; text-align:center;'>&lt;</div>"
							+ "<div style='float:left; width:80%; margin:0; text-align:center;'>"+(artwork.getIndex()+1)+"/"+artwork.getTotalArtworkCount()+"</div>"
							+ "<div class='normal-button"+(artwork.getTotalArtworkCount()==1?" disabled":"")+"' id='ARTWORK_NEXT' style='float:left; width:10%; margin:0; padding:0; text-align:center;'>&gt;</div>"
							
							+ "<div class='normal-button"+(this.getArtworkList().size()==1?" disabled":"")+"' id='ARTWORK_ARTIST_PREVIOUS' style='float:left; width:10%; margin:0; padding:0; text-align:center;'>&lt;</div>"
							+ "<div style='float:left; width:80%; margin:0; text-align:center;'>"+this.getArtworkList().get(artworkIndex).getArtist().getName()+"</div>"
							+ "<div class='normal-button"+(this.getArtworkList().size()==1?" disabled":"")+"' id='ARTWORK_ARTIST_NEXT' style='float:left; width:10%; margin:0; padding:0; text-align:center;'>&gt;</div>"
						+ "</div>");
			} else {
				infoScreenSB.append("<div class='title-button' id='ARTWORK_ADD' style='position:relative; float:right; background:transparent; left:auto; right:4px;'>"+SVGImages.SVG_IMAGE_PROVIDER.getAddIcon()+"</div>");
			}
		}

		infoScreenSB.append(
				"<h6>"
					+Util.capitaliseSentence(this.isPlayerKnowsName()
						?this.getNameIgnoresPlayerKnowledge() + "·" + this.getSurname()
						:this.getName(true))
				+"</h6>"
				+ "<p>"
					+ this.getDescription());
		
		boolean incubated = this.getIncubator()!=null;
		
		boolean append = false;
		if(Main.game.getPlayer().getId().equals(this.getMotherId())) {
			append = true;
			infoScreenSB.append(UtilText.parse(this,
					(incubated
						?"在被"+(this.getIncubator().isPlayer()?"你":this.getIncubator().getName())+"孵化后，[npc.she]出生"
						:"你将其分娩")
					+"于"+this.getBirthdayString()));
			
		} else if(this.isPlayer() || (this.isPlayerKnowsName() && (this.getAffection(Main.game.getPlayer())>=AffectionLevel.POSITIVE_ONE_FRIENDLY.getMinimumValue() || this.isSlave()))) {
			append = true;
			if(this.isDoll()) {
				infoScreenSB.append(UtilText.parse(this, "[npc.She]被制作于"+this.getBirthdayString()));
				
			} else {
				infoScreenSB.append(UtilText.parse(this,
						(incubated
							?"在被"+(this.getIncubator().isPlayer()?"yourself":this.getIncubator().getName())+"孵化后，[npc.she]"
							:"[npc.She]")
						+"出生于"+this.getBirthdayString()));
			}

		}

        if(append) {
            if(Main.getProperties().hasValue(PropertyValue.ageContent)) {
                if(this.isDoll()) {
                    infoScreenSB.append(UtilText.parse(this,
                            ", [npc.she]看起来大概有<span style='color:"+this.getAge().getColour().toWebHexString()+";'>"+Util.intToString(this.getAgeValue())+"</span>岁左右。"));
                } else {
                    infoScreenSB.append(UtilText.parse(this,
                                    ", but"
                                            + (!this.isPlayer()
                                            ? ", due to <span style='color:"  + PresetColour.GENERIC_ARCANE.toWebHexString() + ";'>twisted magic</span> affecting the world,"
                                            : "")
                                            + " [npc.she] " + (this.isPlayer() ? "are" : "is") + " <span style='color:" + this.getAge().getColour().toWebHexString() + ";'>" + Util.intToString(this.getAgeValue()) + "</span> years old.")
//                            + (!this.isPlayer() && generatedAgeOffset > 0 ? " [npc.She] was unnaturally aged by <span style='color:" + AgeCategory.valueOf(this.generatedAgeOffset + MINIMUM_AGE).getColour().toWebHexString()+";'>" + Util.intToString(this.generatedAgeOffset + MINIMUM_AGE)+"</span> years." : "")
                    );
                }

            } else {
                infoScreenSB.append(".");
            }
        }

		infoScreenSB.append("</p>");
		
		infoScreenSB.append("<h6>人物关系</h6>"
				+ "<p>");
		String relationships = this.getRelationshipStrTo(Main.game.getPlayer());
		
		if(!this.isRaceConcealed()) {
			if(!this.isPlayer()) {
				StringBuilder relationshipsSB = new StringBuilder();
				if(this.getPartyLeader()!=null) {
					relationshipsSB.append(UtilText.parse(this, this.getPartyLeader(), "[npc.She]正作为[style.colourCompanion(同伴)]跟随在[npc2.name]身边。"));
				}

				if(!relationships.isEmpty()) {
					if(relationshipsSB.length()>0) {
						relationshipsSB.append("<br/>");
					}
					relationshipsSB.append(UtilText.parse(this, "[npc.She]是你的<span style='color:"+this.getFemininity().getColour().toWebHexString()+"'>"+relationships+"</span>。"));
				}

				List<GameCharacter> charactersPlayerHasEncountered = Main.game.getPlayer().getCharactersEncounteredAsGameCharacters(true);
				
				if(this.isPlayerKnowsName() || Main.game.isDebugMode()) {
					for(NPC npc : Main.game.getAllNPCs()) {
						if(this!=npc && (charactersPlayerHasEncountered.contains(npc) || Main.game.isDebugMode())) {
							String relationshipToOtherNpc = this.getRelationshipStrTo(npc);
							if(!relationshipToOtherNpc.isEmpty()) {
								if(relationshipsSB.length()>0) {
									relationshipsSB.append("<br/>");
								}
								relationshipsSB.append(UtilText.parse(this, npc, "[npc.She]是[npc2.namePos]的<span style='color:"+this.getFemininity().getColour().toWebHexString()+"'>"+relationshipToOtherNpc+"</span>。"));
							}
						}
					}
				}
				
				if(relationshipsSB.length()>0) {
					infoScreenSB.append(relationshipsSB.toString());
					infoScreenSB.append("<br/>");
				}
				
				int affection = (int)this.getAffection(Main.game.getPlayer());
				infoScreenSB.append(AffectionLevel.getDescription(this, Main.game.getPlayer(), true)+" (<span style='color:"+this.getAffectionLevel(Main.game.getPlayer()).getColour().toWebHexString()+";'>"+(affection>0?"+":"")+affection+"</span>)");
				
				for(Entry<String, Float> entry : this.getAffectionMap().entrySet()) {
					try {
						GameCharacter target = Main.game.getNPCById(entry.getKey());
						if(charactersPlayerHasEncountered.contains(target) || Main.game.isDebugMode()) {
							if(!target.isPlayer()
									&& (target.isUnique()
											|| (target.isElemental() && ((Elemental)target).getSummoner().isUnique())
											|| target.isRelatedTo(this)
											|| (target.isSlave() && target.getOwner().isPlayer())
											|| Main.game.getPlayer().getFriendlyOccupants().contains(target.getId()))) {
								infoScreenSB.append("<br/>" + AffectionLevel.getDescription(this, target, true));
								affection = (int)this.getAffection(target);
								infoScreenSB.append("(<span style='color:"+this.getAffectionLevel(target).getColour().toWebHexString()+";'>"+(affection>0?"+":"")+affection+"</span>)");
							}
						}
					} catch (Exception e) {
					}
				}
			}
			if(this.isSlave()) {
				infoScreenSB.append(
							"<br/>"
							+ UtilText.parse(this, "[npc.She]是一名[style.colourArcane(奴隶)]")
							+(getOwner() instanceof Finch
								?"。"
								:"，主人是"+(UtilText.parse(getOwner(), "[npc.name]。")))
							+ ""
							+ ObedienceLevel.getDescription(this, ObedienceLevel.getObedienceLevelFromValue(this.getObedienceValue()), true, true));
			}
			if(!this.isPlayer()) {
				if(!this.getSlavesOwned().isEmpty() && !(this instanceof Finch)) {
					infoScreenSB.append("<br/>"
							+ UtilText.parse(this, "[npc.She]拥有"+Util.intToString(this.getSlavesOwned().size())+"个"+(this.getSlavesOwned().size()==1?"奴隶":"奴隶")+":"));
					List<String> slaveNames = new ArrayList<>();
					for(String id : this.getSlavesOwned()) {
						try {
							slaveNames.add(UtilText.parse(Main.game.getNPCById(id), "[npc.name]"));
						} catch (Exception e) {
							slaveNames.add("未知(id:"+id+")");
						}
					}
					infoScreenSB.append(Util.stringsToStringList(slaveNames, false)+"。");
				}
			}
			infoScreenSB.append("</p>");
			
			infoScreenSB.append("<h6>个性</h6>"
					+ "<p>");
			int i=0;
			for(PersonalityTrait trait : this.getPersonalityTraits()) {
				if(i!=0) {
					infoScreenSB.append("<br/>");
				}
				i++;
				infoScreenSB.append("<b style='color:"+trait.getColour().toWebHexString()+"'>"+Util.capitaliseSentence(trait.getName())+"</b>: "+trait.getDescription(this, false, false));
			}
			if(i==0) {
				if(this.isDoll()) {
					infoScreenSB.append(UtilText.parse(this, "[npc.NameIsFull]是性爱玩偶，因而没有特性。"));
				} else {
					infoScreenSB.append(UtilText.parse(this, "[npc.NameHasFull]的性格很全面，没有格外好或格外坏的特性。"));
				}
			}
			infoScreenSB.append("</p>");
			
			infoScreenSB.append("<h6>外观</h6>"
					+ "<p>"
						+ this.getBodyDescription()
					+ "</p>");

			infoScreenSB.append(
							"<div class='container-full-width'>"
								+ "<details>"
									+ "<summary class='quest-title'>属性</summary>"
									+PhoneDialogue.getBodyStatsPanel(this)
								+ "</details>"
							+"</div>");

			if(includePerkTree) {
				infoScreenSB.append(
							"<div class='container-full-width'>"
								+ "<details>"
									+ "<summary class='quest-title'>天赋树</summary>"
									+ PerkManager.MANAGER.getPerkTreeDisplay(this, false)
								+ "</details>"
							+"</div>");
			}
			
		} else {
			infoScreenSB.append("</p>"
					+ "<br/>"
						+ "<h6>外貌</h6>"
					+ "<p>"
						+ UtilText.parse(this, "由于[npc.namePos]的身体大部分都被遮盖，你对于[npc.her]外表的认识十分有限……")
					+ "</p>"
					+ (Main.game.getPlayer().isKnowsCharacterArea(CoverableArea.ANUS, this)
							?"<p>"
								+ this.getAssDescription(false)
							+ "</p>"
							:"")
					+ (Main.game.getPlayer().isKnowsCharacterArea(CoverableArea.BREASTS, this) && this.hasBreasts()
							?"<p>"
								+ this.getBreastDescription()
							+ "</p>"
							:"")
					+ (Main.game.getPlayer().isKnowsCharacterArea(CoverableArea.BREASTS_CROTCH, this) && this.hasBreastsCrotch()
							?"<p>"
								+ this.getBreastCrotchDescription()
							+ "</p>"
							:"")
					+ (Main.game.getPlayer().isKnowsCharacterArea(CoverableArea.PENIS, this) && this.hasPenis()
							?"<p>"
								+ this.getPenisDescription()
							+ "</p>"
							:"")
					+ (Main.game.getPlayer().isKnowsCharacterArea(CoverableArea.VAGINA, this) && this.hasVagina()
							?"<p>"
								+ this.getVaginaDescription()
							+ "</p>"
							:"")
                    + (Main.game.getPlayer().isKnowsCharacterArea(CoverableArea.TUSSY, this) && this.hasVagina()
                    ?"<p>"
                    + this.getTussyDescriptor()
                    + "</p>"
                    :""));
		}
		
		return infoScreenSB.toString();
	}

