	public Gender getGender() {
		return body.getGender();
	}
	
	public boolean isFeminine() {
		boolean isFeminine = body==null || body.isFeminine();
		
		if(body!=null) {
			if(Femininity.valueOf(getFemininityValue()) == Femininity.ANDROGYNOUS) {
				switch(Main.getProperties().androgynousIdentification){
					case FEMININE:
						isFeminine = true;
						break;
					case CLOTHING_FEMININE:
						isFeminine = getClothingAverageFemininity() >= 50;
						break;
					case CLOTHING_MASCULINE:
						isFeminine = getClothingAverageFemininity() > 50;
						break;
					case MASCULINE:
						isFeminine = false;
						break;
					default:
						break;
				}
			}
		}
		
		return isFeminine;
	}

	/**
	 * @return The nocturnality of this character's current Subspecies.
	 * <br/><b>Note:</b> This is derived from the <code>getSubspecies()</code> method, which does not take into account the character's 'true' Subspecies (if they are a demon masquerading as another species).
	 */
	public Nocturnality getNocturnality() {
		return getSubspecies().getNocturnality();
	}
	
	/**
	 * @return The race which this character appears to be. Use getTrueRace() or do some checks with getSubspeciesOverride() to get their true race, but for 99.9% of the time, that won't be necessary and this method is fine to use.
	 */
	public AbstractRace getRace() {
		return getSubspecies().getRace();
	}

	/**
	 * @return This character's true race. If this character does not have a subspecies override, this will be the same as getRace(). If they do have an override, however, it will return the race of that override.
	 */
	public AbstractRace getTrueRace() {
		if(this.getSubspeciesOverride()!=null) {
			return this.getSubspeciesOverride().getRace();
		}
		return getRace();
	}
	
	/**
	 * @return The subspecies which this character appears to be. Use getTrueSubspecies() or do some checks with getSubspeciesOverride() to get their true Subspecies, but for 99.9% of the time, that won't be necessary and this method is fine to use.
	 */
	public AbstractSubspecies getSubspecies() {
        if (body == null) return Subspecies.HUMAN;
		return body.getSubspecies();
	}

	/**
	 * Get the subspecies which this character appears to be if they were made of flesh.
	 * @return The subspecies.
	 */
	public AbstractSubspecies getFleshSubspecies() {
		return body.getFleshSubspecies();
	}

	/**
	 * @return This character's true subspecies. If this character does not have a subspecies override, this will be the same as getSubspecies(). If they do have an override, however, it will return that override.
	 */
	public AbstractSubspecies getTrueSubspecies() {
		if(this.getSubspeciesOverride()!=null) {
			return this.getSubspeciesOverride();
		}
		return getSubspecies();
	}
	
	/**
	 * Ferals, elementals, demons, angels, slimes, and dolls can't have their race transformed.
	 */
	public boolean isAbleToHaveRaceTransformed() {
		return !this.isFeral()
				&& !this.hasPerkAnywhereInTree(Perk.DOLL_ARCANE_1)
				&& !this.getTrueSubspecies().isAbleToSelfTransform();
	}
	
	/**
	 * @return True if this character's self-transform menu can be accessed.
	 */
	public boolean isAbleToSelfTransform() {
		return getUnableToTransformDescription().isEmpty();
	}
	
	/**
	 * @return A description of why this character cannot self-transform. Returns an empty String if they are able to self-transform.
	 */
	public String getUnableToTransformDescription() {
		if(!getTrueSubspecies().isAbleToSelfTransform() || this.isDoll()) {
			return UtilText.parse(this, "由于[npc.sheIsFull]是个[npc.a_race]，[npc.name]无法随意转化[npc.her]的身体！");
		}
		if(this.isFeral()) {
			return UtilText.parse(this, "由于[npc.sheIsFull]是个兽态[npc.race]，[npc.name]无法转化[npc.her]的身体！");
		}
		if(this.getClothingCurrentlyEquipped().stream().anyMatch(c -> c.isSelfTransformationInhibiting())) {
			return UtilText.parse(this, "尽管[npc.nameIsFull]通常能够自我转化，但[npc.she]现在无法这么做，因为[npc.her]衣物上的附魔阻止了[npc.her]使用自我转化的能力！");
		}
		if(this.getTattoos().values().stream().anyMatch(c -> c.isSelfTransformationInhibiting())) {
			return UtilText.parse(this, "尽管[npc.nameIsFull]通常能够自我转化，但[npc.she]现在无法这么做，因为[npc.her]纹身上的附魔阻止了[npc.her]使用自我转化的能力！");
		}
		if(Main.game.isInSex() && Main.sex.isSelfTransformDisabled(this)) {
			return UtilText.parse(this, "尽管[npc.nameIsFull]通常能够自我转化，但[npc.she]无法在性爱场景中这么做！");
		}
		return "";
	}
	
	public String applyRandomTransformation(AbstractSubspecies subspeciesOfRandomPart) {
		List<BodyPartInterface> potentialParts = new ArrayList<>();
		potentialParts.add(this.getBody().getEar());
		potentialParts.add(this.getBody().getEye());
		potentialParts.add(this.getBody().getHair());

		potentialParts.add(this.getBody().getAntenna());
		potentialParts.add(this.getBody().getHorn());
		potentialParts.add(this.getBody().getTail());
		potentialParts.add(this.getBody().getWing());

		potentialParts.add(this.getBody().getFace());
		potentialParts.add(this.getBody().getTorso());
		potentialParts.add(this.getBody().getArm());
		potentialParts.add(this.getBody().getLeg());

		potentialParts.add(this.getBody().getAss());
		potentialParts.add(this.getBody().getBreast());
		if(this.hasPenis()) {
			potentialParts.add(this.getBody().getPenis());
		}
		if(this.hasVagina()) {
			potentialParts.add(this.getBody().getVagina());
		}

		BodyPartInterface randomPart = Util.randomItemFrom(potentialParts);

		// Apply the randomly-chosen part transformation:

		if(randomPart instanceof Ear) {
			return this.setEarType(subspeciesOfRandomPart.getRace().getRacialBody().getEarType());
		}
		if(randomPart instanceof Eye) {
			return this.setEyeType(subspeciesOfRandomPart.getRace().getRacialBody().getEyeType());
		}
		if(randomPart instanceof Hair) {
			return this.setHairType(subspeciesOfRandomPart.getRace().getRacialBody().getHairType());
		}

		if(randomPart instanceof Antenna) {
			return this.setAntennaType(subspeciesOfRandomPart.getRace().getRacialBody().getRandomAntennaType(false));
		}
		if(randomPart instanceof Horn) {
			return this.setHornType(subspeciesOfRandomPart.getRace().getRacialBody().getRandomHornType(false));
		}
		if(randomPart instanceof Tail) {
			return this.setTailType(subspeciesOfRandomPart.getRace().getRacialBody().getRandomTailType(false));
		}
		if(randomPart instanceof Wing) {
			return this.setWingType(subspeciesOfRandomPart.getRace().getRacialBody().getRandomWingType(false));
		}

		if(randomPart instanceof Face) {
			return this.setFaceType(subspeciesOfRandomPart.getRace().getRacialBody().getFaceType());
		}
		if(randomPart instanceof Torso) {
			return this.setTorsoType(subspeciesOfRandomPart.getRace().getRacialBody().getTorsoType());
		}
		if(randomPart instanceof Arm) {
			return this.setArmType(subspeciesOfRandomPart.getRace().getRacialBody().getArmType());
		}
		if(randomPart instanceof Leg) {
			return this.setLegType(subspeciesOfRandomPart.getRace().getRacialBody().getLegType());
		}

		if(randomPart instanceof Ass) {
			return this.setAssType(subspeciesOfRandomPart.getRace().getRacialBody().getAssType());
		}
		if(randomPart instanceof Breast) {
			StringBuilder sb = new StringBuilder();
			sb.append(this.setBreastType(subspeciesOfRandomPart.getRace().getRacialBody().getBreastType()));
			if(this.hasBreastsCrotch()) {
				sb.append(this.setBreastCrotchType(subspeciesOfRandomPart.getRace().getRacialBody().getBreastType()));
			}
			return sb.toString();
		}
		if(randomPart instanceof Penis) {
			return this.setPenisType(subspeciesOfRandomPart.getRace().getRacialBody().getPenisType());
		}
		if(randomPart instanceof Vagina) {
			return this.setVaginaType(subspeciesOfRandomPart.getRace().getRacialBody().getVaginaType());
		}

		return "";
	}

