	public void addTattoo(InventorySlot invSlot, Tattoo tattoo) {
		removeTattoo(invSlot);
		tattoos.put(invSlot, tattoo);
		applyEquipTattooEffects(tattoo);
	}

	/**
	 * Tattoo addition method mainly for use in external files. After adding tattoo, use getTattooInSlot(invSlot).setWriting() and getTattooInSlot(invSlot).setCounter() methods to set writing/counter for tattoo.
	 */
	public void addTattoo(InventorySlot invSlot, AbstractTattooType type, Colour primaryColour, Colour secondaryColour, Colour tertiaryColour, boolean glowing) {
		removeTattoo(invSlot);
		Tattoo tattoo = new Tattoo(
				type,
				primaryColour,
				secondaryColour,
				tertiaryColour,
				glowing,
				null,
				null);
		tattoos.put(invSlot, tattoo);
		applyEquipTattooEffects(tattoo);
	}
	
	public void removeTattoo(InventorySlot invSlot) {
		Tattoo tattoo = tattoos.get(invSlot);
		if(tattoo!=null) {
			applyUnequipTattooEffects(tattoo);
			tattoos.remove(invSlot);
		}
	}
	
	public Tattoo getTattooInSlot(InventorySlot invSlot) {
		if(tattoos.containsKey(invSlot)) {
			return tattoos.get(invSlot);
		}
		return null;
	}
	
	private void applyEquipTattooEffects(Tattoo tattoo) {
		for (Entry<AbstractAttribute, Integer> e : tattoo.getAttributeModifiers().entrySet()) {
			incrementBonusAttribute(e.getKey(), e.getValue());
		}
		
		for(ItemEffect ie : tattoo.getEffects()) {
			if(ie.getSecondaryModifier()!=null && ie.getSecondaryModifier().getFetish()!=null) {
				AbstractFetish associatedFetish = ie.getSecondaryModifier().getFetish();
				switch(ie.getPotency()) {
					case MINOR_BOOST:
						clothingFetishDesireModifiersMap.putIfAbsent(ie.getSecondaryModifier().getFetish(), 0);
						clothingFetishDesireModifiersMap.put(associatedFetish, clothingFetishDesireModifiersMap.get(associatedFetish) + 1);
						break;
					case BOOST:
						clothingFetishDesireModifiersMap.putIfAbsent(associatedFetish, 0);
						clothingFetishDesireModifiersMap.put(associatedFetish, clothingFetishDesireModifiersMap.get(associatedFetish) + 2);
						break;
					case MAJOR_BOOST:
					case SPECIAL:
						fetishesFromClothing.add(associatedFetish);
						if(!this.isDoll()) {
							applyFetishGainEffects(associatedFetish);
						}
						break;
					case MINOR_DRAIN:
						clothingFetishDesireModifiersMap.putIfAbsent(associatedFetish, 0);
						clothingFetishDesireModifiersMap.put(associatedFetish, clothingFetishDesireModifiersMap.get(associatedFetish) - 1);
						break;
					case DRAIN:
						clothingFetishDesireModifiersMap.putIfAbsent(associatedFetish, 0);
						clothingFetishDesireModifiersMap.put(associatedFetish, clothingFetishDesireModifiersMap.get(associatedFetish) - 2);
						break;
					case MAJOR_DRAIN:
						clothingFetishDesireModifiersMap.putIfAbsent(associatedFetish, 0);
						clothingFetishDesireModifiersMap.put(associatedFetish, clothingFetishDesireModifiersMap.get(associatedFetish) - 999);
						break;
				}
			}
			// Creampie retention:
			if(Main.game.isStarted() && ie.getPrimaryModifier()==TFModifier.CLOTHING_CREAMPIE_RETENTION) {
				switch(ie.getSecondaryModifier()) {
					case TF_FACE:
						addCreampieRetentionArea(SexAreaOrifice.MOUTH);
						break;
					case TF_ASS:
						addCreampieRetentionArea(SexAreaOrifice.ANUS);
						break;
					case TF_VAGINA:
						addCreampieRetentionArea(SexAreaOrifice.VAGINA);
						break;
					case TF_VAGINA_URETHRA:
						addCreampieRetentionArea(SexAreaOrifice.URETHRA_VAGINA);
						break;
					case TF_PENIS_URETHRA:
						addCreampieRetentionArea(SexAreaOrifice.URETHRA_PENIS);
						break;
					case TF_BREASTS:
						addCreampieRetentionArea(SexAreaOrifice.NIPPLE);
						break;
					case TF_BREASTS_CROTCH:
						addCreampieRetentionArea(SexAreaOrifice.NIPPLE_CROTCH);
						break;
					case TF_SPINNERET:
						addCreampieRetentionArea(SexAreaOrifice.SPINNERET);
						break;
                        case TF_TUSSY:
						addCreampieRetentionArea(SexAreaOrifice.TUSSY);
						break;
					default:
						break;
				}
			}
		}
	}
	
	private void applyUnequipTattooEffects(Tattoo tattoo) {
		for (Entry<AbstractAttribute, Integer> e : tattoo.getAttributeModifiers().entrySet()) {
			incrementBonusAttribute(e.getKey(), -e.getValue());
		}
		
		for(ItemEffect ie : tattoo.getEffects()) {
			if(ie.getSecondaryModifier()!=null && ie.getSecondaryModifier().getFetish()!=null) {
				AbstractFetish associatedFetish = ie.getSecondaryModifier().getFetish();
				switch(ie.getPotency()) {
					case MINOR_BOOST:
						clothingFetishDesireModifiersMap.put(associatedFetish, clothingFetishDesireModifiersMap.get(associatedFetish) - 1);
						break;
					case BOOST:
						clothingFetishDesireModifiersMap.put(associatedFetish, clothingFetishDesireModifiersMap.get(associatedFetish) - 2);
						break;
					case MAJOR_BOOST:
					case SPECIAL:
						fetishesFromClothing.remove(associatedFetish);
						if(this.isDoll()) {
							applyFetishLossEffects(associatedFetish);
						}
						break;
					case MINOR_DRAIN:
						clothingFetishDesireModifiersMap.put(associatedFetish, clothingFetishDesireModifiersMap.get(associatedFetish) + 1);
						break;
					case DRAIN:
						clothingFetishDesireModifiersMap.put(associatedFetish, clothingFetishDesireModifiersMap.get(associatedFetish) + 2);
						break;
					case MAJOR_DRAIN:
						clothingFetishDesireModifiersMap.putIfAbsent(associatedFetish, 0);
						clothingFetishDesireModifiersMap.put(associatedFetish, clothingFetishDesireModifiersMap.get(associatedFetish) + 999);
						break;
				}
			}
			// Creampie retention:
			if(Main.game.isStarted() && ie.getPrimaryModifier()==TFModifier.CLOTHING_CREAMPIE_RETENTION) {
				switch(ie.getSecondaryModifier()) {
					case TF_FACE:
						removeCreampieRetentionArea(SexAreaOrifice.MOUTH);
						break;
					case TF_ASS:
						removeCreampieRetentionArea(SexAreaOrifice.ANUS);
						break;
					case TF_VAGINA:
						removeCreampieRetentionArea(SexAreaOrifice.VAGINA);
						break;
					case TF_VAGINA_URETHRA:
						removeCreampieRetentionArea(SexAreaOrifice.URETHRA_VAGINA);
						break;
					case TF_PENIS_URETHRA:
						removeCreampieRetentionArea(SexAreaOrifice.URETHRA_PENIS);
						break;
					case TF_BREASTS:
						removeCreampieRetentionArea(SexAreaOrifice.BREAST);
						break;
					case TF_BREASTS_CROTCH:
						removeCreampieRetentionArea(SexAreaOrifice.BREAST_CROTCH);
						break;
					case TF_SPINNERET:
						removeCreampieRetentionArea(SexAreaOrifice.SPINNERET);
						break;
                    case TF_TUSSY:
						removeCreampieRetentionArea(SexAreaOrifice.TUSSY);
						break;
					default:
						break;
				}
			}
		}
	}

