	/**
	 * @return The character's height in cm.
	 */
	public int getHeightValue() {
        if (body == null) return -1;
		return body.getHeightValue();
	}
	
	public Height getHeight() {
		return body.getHeight();
	}

	public boolean isShortStature() {
		return body.isShortStature();
	}
	
	public boolean isSizeDifferenceShorterThan(GameCharacter character) {
		return this.getHeightValue() < character.getHeightValue()*0.6f;
	}
	
	public boolean isSizeDifferenceTallerThan(GameCharacter character) {
		return character.getHeightValue() < this.getHeightValue()*0.6f;
	}
	
	public int getMinimumHeight() {
		if(this.isFeral()) {
			return Math.min(Height.NEGATIVE_TWO_MINIMUM.getMinimumValue(), (int) (this.getFeralAttributes().getSize()*0.5f));
		}
		return this.getTrueSubspecies().isShortStature()
				?Height.NEGATIVE_TWO_MINIMUM.getMinimumValue()
				:Height.getShortStatureCutOff();
	}
	
	public int getMaximumHeight() {
//		if(this.isFeral()) {
//			return Math.max(Height.SEVEN_COLOSSAL.getMaximumValue(), (int) (this.getFeralAttributes().getSize()*2f));
//		}

		return this.getTrueSubspecies().isShortStature()
				?Height.getShortStatureCutOff()-1
				:Height.SEVEN_COLOSSAL.getMaximumValue();
	}

	public String setHeight(int height) {
		return setHeight(height, false);
	}
	/**
	 * @return Formatted description of height change.
	 */
	public String setHeight(int height, boolean ignoreHeightRestrictions) {
		if(this.getBody()==null) {
			return "";
		}

		if(!ignoreHeightRestrictions) {
			height = Math.min(getMaximumHeight(), Math.max(getMinimumHeight(), height));
		}
		
		if (body.getHeightValue() < height) {
			if (body.setHeight(height)) {
				return isPlayer()
						? "<p class='center'>"
							+ "你附近的世界仿佛突然向你远离，但片刻过后，你意识到不过是自己<b style='color:" + PresetColour.TRANSFORMATION_GENERIC.toWebHexString() + ";'>长高了</b>。"
							+ "<br/>"
							+ "你现在身高<b>" + Units.size(getHeightValue(), Units.UnitType.LONG) + "</b>。"
						+ "</p>"
						: UtilText.parse(this,
							"<p class='center'>"
								+ "[npc.She]左右摇晃了一下身子，忽然差点失去平衡，这是因为[npc.sheIs]<b style='color:" + PresetColour.TRANSFORMATION_GENERIC.toWebHexString() + ";'>长高了</b>。"
							+ "</p>");
			}
			
		} else if (body.getHeightValue() > height) {
			if (body.setHeight(height)) {
				return isPlayer()
						? "<p class='center'>"
							+ "你附近的世界仿佛突然向你靠近，但片刻过后，你意识到不过是自己<b style='color:" + PresetColour.TRANSFORMATION_GENERIC.toWebHexString() + ";'>变矮了</b>。"
							+ "<br/>"
							+ "你现在身高<b>" + Units.size(getHeightValue(), Units.UnitType.LONG) + "</b>。"
						+ "</p>"
						: UtilText.parse(this,
							"<p class='center'>"
								+ "[npc.She]身形收缩，<b style='color:" + PresetColour.TRANSFORMATION_GENERIC.toWebHexString() + ";'>显然矮了不少</b>。"
							+ "</p>");
			}
		}
		
		if(isPlayer()) {
			return "<p class='center'>"
					+ "<span style='color:" + PresetColour.TEXT_GREY.toWebHexString() + ";'>你的身高并无变化……</span>"
				+ "</p>";
		} else {
			return "<p class='center'>"
					+ UtilText.parse(this, "<span style='color:" + PresetColour.TEXT_GREY.toWebHexString() + ";'>[npc.NamePos]的身高并无变化……</span>")
				+ "</p>";
		}
	}
	
	/**
	 * @return Formatted description of height change.
	 */
	public String incrementHeight(int increment, boolean ignoreHeightRestrictions) {
		return setHeight(getHeightValue() + increment, ignoreHeightRestrictions);
	}

